    key_decisions: List[str] = Field(description="3-6 decisiones de diseño donde un profesional debe elegir entre alternativas.")
    common_pitfalls: List[str] = Field(description="3-6 errores o fuentes de fallo habituales mencionados o deducibles del temario.")
    case_archetypes: List[str] = Field(description="3-5 tipos de situaciones reales en las que un profesional de este campo aplicaría el temario.")


