class BatchExamEvaluation(BaseModel):
    evaluations: List[WrittenItemGrading] = Field(description="Lista con la evaluación de cada pregunta escrita del examen.")


# ==================== UTILIDADES DE CASOS PRÁCTICOS ====================

def _bullets(items) -> str:
    return "\n".join(f"• {str(i).strip()}" for i in (items or []) if str(i).strip())


def _case_type_label(case: dict) -> str:
    return CASE_TYPE_LABELS.get(str(case.get("case_type", "")).strip().upper(), "")


def _case_reference_sections(case: dict):
    """Devuelve [(titulo, texto)] con la solución de referencia de un caso (tolerante a campos ausentes)."""
    sections = []
    wf = case.get("expected_workflow") or []
    if wf:
        lines = []
        for i, st in enumerate(wf, 1):
            lines.append(
                f"{i}. {st.get('step', '')}: {st.get('action', '')}\n"
                f"   ▸ {st.get('technique_or_tool', '')} — {st.get('justification', '')}"
            )
        sections.append(("🧭 Esquema general de referencia", "\n".join(lines)))
    tr = case.get("technique_tradeoffs") or []
    if tr:
        lines = [
            f"• {t.get('technique', '')} [{t.get('verdict', '')}]\n   + {t.get('advantage', '')}\n   − {t.get('limitation', '')}"
            for t in tr
        ]
        sections.append(("⚖️ Técnicas: ventajas, limitaciones y decisión", "\n".join(lines)))
    if case.get("resources"):
        sections.append(("🗄️ Bases de datos / herramientas", _bullets(case["resources"])))
    if case.get("controls_and_validation"):
        sections.append(("✅ Controles y validación", _bullets(case["controls_and_validation"])))
    if case.get("pitfalls"):
        sections.append(("⚠️ Errores típicos", _bullets(case["pitfalls"])))
    if case.get("step_by_step_solution"):
        sections.append(("📝 Resumen de la solución", case["step_by_step_solution"]))
    return sections


def _case_reference_text(case: dict) -> str:
    parts = [f"{t}\n{b}" for t, b in _case_reference_sections(case)]
    return "\n\n".join(parts) if parts else case.get("step_by_step_solution", "")


def _format_syllabus_map(m) -> str:
    """Convierte el mapa del temario en un bloque compacto para meter en prompts."""
    if not m:
        return ""
    out = [f"MAPA DEL TEMARIO (ya analizado; úsalo como base de conocimiento):",
           f"Campo: {m.get('domain', '')} | Tipo: {m.get('domain_kind', '')}"]
    out.append("Técnicas y métodos:")
    for t in m.get("techniques", []):
        out.append(
            f"- {t.get('name', '')} [{t.get('category', '')}]: {t.get('purpose', '')} "
            f"| Ventajas: {'; '.join(t.get('advantages', []))} "
            f"| Limitaciones: {'; '.join(t.get('limitations', []))} "
            f"| Elegir cuando: {t.get('when_to_use', '')}"
        )
    res = m.get("resources", [])
    if res:
        out.append("Bases de datos / herramientas / normas:")
        for r in res:
            tag = "" if r.get("in_syllabus", True) else " (externo al temario)"
            out.append(f"- {r.get('name', '')} [{r.get('kind', '')}]{tag}: {r.get('use', '')}")
    if m.get("typical_workflow"):
        out.append("Flujo típico: " + " → ".join(m["typical_workflow"]))
    if m.get("key_decisions"):
        out.append("Decisiones clave: " + " | ".join(m["key_decisions"]))
    if m.get("common_pitfalls"):
        out.append("Errores habituales: " + " | ".join(m["common_pitfalls"]))
    if m.get("case_archetypes"):
        out.append("Situaciones reales típicas: " + " | ".join(m["case_archetypes"]))
    return "\n".join(out)


# ==================== UTILIDADES DE PROCESAMIENTO ====================

_PH_OPEN, _PH_CLOSE = "\ue000", "\ue001"
_KEYWORD_LETTERS_RE = re.compile(
    r"(\b(?:opci[oó]n|opciones|respuesta|respuestas|alternativa|alternativas|letra|letras|inciso|incisos|apartado|apartados)\s+)"
    r"(\(?[ABCD]\)?(?:\s*(?:,|/|\by\b|\be\b|\bo\b|\bu\b)\s*\(?[ABCD]\)?)*)",
    re.IGNORECASE,
)
_CHAIN_LETTERS_RE = re.compile(r"(?<![\w])[ABCD](?:\s*,\s*[ABCD])*\s+(?:y|o|e)\s+[ABCD](?![\w])")
_ARTICLE_LETTER_RE = re.compile(r"(\b(?:la|las|en la|de la|con la)\s+)([ABCD])\b")
_PAREN_LETTER_RE = re.compile(r"\(([ABCD])\)")
_LABEL_LETTER_RE = re.compile(r"(?<![\w])([ABCD])\)")


def _remap_letters_in_text(text: str, mapping: dict) -> str:
    """Cambia las referencias a letras de opción (A/B/C/D) de un texto según `mapping` (letra vieja -> letra nueva).
    Usa marcadores temporales para que una letra no se transforme dos veces."""
    if not text or not mapping:
        return text

    def ph(letter: str) -> str:
        return f"{_PH_OPEN}{mapping.get(letter, letter)}{_PH_CLOSE}"

    def _letters_only(chunk: str) -> str:
        return re.sub(r"[ABCD]", lambda m: ph(m.group(0)), chunk)

    def _kw(m):
        letters_part = m.group(2)
        # solo letras mayúsculas: evita confundir la preposición "a" ("respuesta a la pregunta")
        return m.group(1) + _letters_only(letters_part)

    out = _CHAIN_LETTERS_RE.sub(lambda m: _letters_only(m.group(0)), text)
    out = _KEYWORD_LETTERS_RE.sub(_kw, out)
    out = _ARTICLE_LETTER_RE.sub(lambda m: m.group(1) + ph(m.group(2)), out)
    out = _PAREN_LETTER_RE.sub(lambda m: "(" + ph(m.group(1)) + ")", out)
    out = _LABEL_LETTER_RE.sub(lambda m: ph(m.group(1)) + ")", out)
    return re.sub(f"{_PH_OPEN}([ABCD]){_PH_CLOSE}", lambda m: m.group(1), out)


def _shuffle_options(mcq: dict) -> dict:
    opts = mcq.get("options", [])
    correct_letter = str(mcq.get("correct_letter", "")).strip().upper()
    if len(opts) != 4 or correct_letter not in LETTERS:
        return mcq
    correct_idx = LETTERS.index(correct_letter)
    correct_text = opts[correct_idx]
    indexed = list(enumerate(opts))
    random.shuffle(indexed)
    new_opts = [text for _, text in indexed]
    new_correct_idx = next(i for i, (orig_idx, _) in enumerate(indexed) if orig_idx == correct_idx)
    assert new_opts[new_correct_idx] == correct_text
    mcq["options"] = new_opts
    mcq["correct_letter"] = LETTERS[new_correct_idx]

    # La explicación suele citar letras ("la A es falsa...") y esas letras cambian al barajar:
    # las traducimos a la posición nueva para que expliquen la opción correcta.
    letter_map = {LETTERS[orig_idx]: LETTERS[new_idx] for new_idx, (orig_idx, _) in enumerate(indexed)}
    if isinstance(mcq.get("explanation"), str):
        mcq["explanation"] = _remap_letters_in_text(mcq["explanation"], letter_map)
    return mcq


def _normalize_mcq(mcq: dict) -> dict:
    opts = mcq.get("options", [])
    cleaned = []
    for o in opts:
        s = str(o).strip()
        if len(s) >= 2 and s[0].upper() in LETTERS and s[1] in ").:- ":
            s = s[2:].strip()
        elif len(s) >= 3 and s[0] == "(" and s[1].upper() in LETTERS and s[2] == ")":
            s = s[3:].strip()
        cleaned.append(s)
    mcq["options"] = cleaned
    return _shuffle_options(mcq)


def _format_capitalized_term(term: str) -> str:
    t = term.strip()
    if not t:
        return t
    return t[0].upper() + t[1:]


# ==================== ANTIRREPETICIÓN INTELIGENTE ====================
# Detecta temas "casi iguales" (otra redacción, plurales, tildes, orden de palabras...) en vez de
# comparar solo texto exacto.

_STOPWORDS = {
    "de", "del", "la", "las", "el", "los", "lo", "un", "una", "unos", "unas", "y", "e", "o", "u", "a", "al",
    "en", "por", "para", "con", "sin", "sobre", "entre", "su", "sus", "que", "se", "es", "son", "como",
    "segun", "ante", "desde", "hacia", "tipo", "tipos", "concepto", "conceptos", "proceso", "procesos",
}


def _norm_text(text: str) -> str:
    t = unicodedata.normalize("NFD", str(text or "").lower())
    t = "".join(ch for ch in t if unicodedata.category(ch) != "Mn")
    t = "".join(ch if ch.isalnum() else " " for ch in t)
    return " ".join(t.split())


def _stem_token(w: str) -> str:
    if len(w) > 4 and w.endswith("es"):
        w = w[:-2]
    elif len(w) > 4 and w.endswith("s"):
        w = w[:-1]
    return w[:6]


class _TextKey:
    """Forma normalizada de un tema o pregunta: texto limpio + conjunto de raíces de palabras."""

    __slots__ = ("norm", "stems", "tags")

    def __init__(self, text: str):
        self.norm = _norm_text(text)
        words = [w for w in self.norm.split() if w not in _STOPWORDS]
        self.stems = frozenset(_stem_token(w) for w in words)
        # números y siglas cortas ("b6", "b12", "ii", "c4") distinguen temas casi idénticos
        self.tags = frozenset(w for w in words if len(w) <= 2 or any(c.isdigit() for c in w))


def _keys_similar(a: _TextKey, b: _TextKey, jaccard_min: float = 0.6, seq_min: float = 0.88) -> bool:
    if not a.norm or not b.norm:
        return False
    if a.norm == b.norm:
        return True
    if a.tags != b.tags:
        return False
    if a.stems and b.stems:
        inter = len(a.stems & b.stems)
        union = len(a.stems | b.stems)
        if union and inter / union >= jaccard_min:
            return True
        small, large = (a.stems, b.stems) if len(a.stems) <= len(b.stems) else (b.stems, a.stems)
        # "Cromatografía de afinidad" vs "Cromatografía de afinidad por metales": uno contenido en el otro
        if len(small) >= 2 and small <= large and len(large) - len(small) <= 1:
            return True
    return SequenceMatcher(None, a.norm, b.norm).ratio() >= seq_min


class _TopicSet:
    """Conjunto de temas con `in` y `add` tolerantes a variaciones (misma interfaz que un set de str)."""

    def __init__(self, topics=()):
        self._keys: list = []
        self._exact: set = set()
        self._entries: list = []
        for t in topics:
            self.add(t)

    def __contains__(self, topic) -> bool:
        key = _TextKey(topic)
        if not key.norm:
            return False
        if key.norm in self._exact:
            return True
        return any(_keys_similar(key, k) for k in self._keys)

    def add(self, topic) -> None:
        key = _TextKey(topic)
        if key.norm and key.norm not in self._exact:
            self._exact.add(key.norm)
            self._keys.append(key)

    @classmethod
    def from_history(cls, entries):
        ts = cls()
        for e in entries:
            if e.get("topic"):
                ts.add_item(e.get("topic", ""), e.get("approach", ""), e.get("question", ""))
        return ts

    def add_item(self, topic, approach="", question="") -> None:
        """Registra un tema junto con su enfoque y su enunciado."""
        self.add(topic)
        tk = _TextKey(topic)
        if tk.norm:
            self._entries.append((tk, _TextKey(approach), _TextKey(question)))

    def blocks_item(self, topic, approach="", question="") -> bool:
        """True si la pregunta es repetida. Un tema ya visto SE PERMITE si se aborda con un enfoque distinto;
        se bloquea si el enfoque es el mismo o si el enunciado es casi igual a uno anterior."""
        tk = _TextKey(topic)
        if not tk.norm:
            return True
        ak, qk = _TextKey(approach), _TextKey(question)
        for t2, a2, q2 in self._entries:
            if not _keys_similar(tk, t2):
                continue
            if qk.norm and q2.norm and _keys_similar(qk, q2, jaccard_min=0.6, seq_min=0.85):
                return True
            if ak.norm and a2.norm and _keys_similar(ak, a2, jaccard_min=0.5, seq_min=0.85):
                return True
        return False

    def __len__(self) -> int:
        return len(self._keys)

    def __iter__(self):
        return (k.norm for k in self._keys)


