    def show_auth_screen(self):
        """Pantalla inicial de login/registro. Solo tras autenticarse se muestra la app."""
        self.page.clean()

        title = ft.Text("ismael_prd — Exam Suite", size=26, weight=ft.FontWeight.BOLD, color=ACCENT_TEAL)
        subtitle = ft.Text("Accede o crea una cuenta para continuar", size=13, color=TEXT_MUTED)

        username_field = ft.TextField(
            label="Usuario",
            width=340,
            bgcolor=BG_INPUT,
            border_color=BORDER_SUBTLE,
            focused_border_color=ACCENT_TEAL,
            border_radius=12,
            color=TEXT_WHITE,
            content_padding=ft.Padding.symmetric(horizontal=14, vertical=12),
        )
        password_field = ft.TextField(
            label="Contraseña",
            password=True,
            can_reveal_password=True,
            width=340,
            bgcolor=BG_INPUT,
            border_color=BORDER_SUBTLE,
            focused_border_color=ACCENT_TEAL,
            border_radius=12,
            color=TEXT_WHITE,
            content_padding=ft.Padding.symmetric(horizontal=14, vertical=12),
        )
        message = ft.Text("", color=ACCENT_CORAL, size=13)

        def do_login(e):
            user = (username_field.value or "").strip()
            pwd = password_field.value or ""
            if not user or not pwd:
                message.value = "Rellena usuario y contraseña."
                message.color = ACCENT_AMBER
                self.page.update()
                return
            if verify_user(user, pwd):
                self.current_user = user
                self.page.clean()
                self.build_main_layout()
                self.page.update()
            else:
                message.value = "Usuario o contraseña incorrectos."
                message.color = ACCENT_CORAL
                self.page.update()

        def do_register(e):
            user = (username_field.value or "").strip()
            pwd = password_field.value or ""
            if not user or not pwd:
                message.value = "Rellena usuario y contraseña."
                message.color = ACCENT_AMBER
                self.page.update()
                return
            if len(pwd) < 4:
                message.value = "La contraseña debe tener al menos 4 caracteres."
                message.color = ACCENT_AMBER
                self.page.update()
                return
            if register_user(user, pwd):
                message.value = "Registro exitoso. Ahora inicia sesión."
                message.color = ACCENT_TEAL
            else:
                message.value = "El usuario ya existe o hubo un error."
                message.color = ACCENT_CORAL
            self.page.update()

        card = self.create_glow_card(
            theme_idx=0,
            padding=32,
            content=ft.Column(
                horizontal_alignment=ft.CrossAxisAlignment.CENTER,
                spacing=16,
                controls=[
                    ft.Icon(ft.Icons.SCHOOL_ROUNDED, size=56, color=ACCENT_TEAL),
                    title,
                    subtitle,
                    username_field,
                    password_field,
                    ft.Row(
                        alignment=ft.MainAxisAlignment.CENTER,
                        spacing=12,
                        controls=[
                            ft.Button(
                                content="Entrar",
                                icon=ft.Icons.LOGIN_ROUNDED,
                                bgcolor=ACCENT_TEAL,
                                color=BG_OUTER,
                                height=42,
                                style=ft.ButtonStyle(
                                    shape=ft.RoundedRectangleBorder(radius=12),
                                    text_style=ft.TextStyle(weight=ft.FontWeight.BOLD),
                                ),
                                on_click=do_login,
                            ),
                            ft.OutlinedButton(
                                content="Crear cuenta",
                                icon=ft.Icons.PERSON_ADD_ROUNDED,
                                style=ft.ButtonStyle(
                                    color=TEXT_WHITE,
                                    shape=ft.RoundedRectangleBorder(radius=12),
                                ),
                                on_click=do_register,
                            ),
                        ],
                    ),
                    message,
                ],
            ),
        )

        self.page.add(
            ft.Container(
                expand=True,
                alignment=ft.Alignment(0.0, 0.0),
                padding=20,
                content=ft.Container(width=420, content=card),
            )
        )
        self.page.update()

    def logout(self, e=None):
        """Cierra sesión y vuelve al login."""
        self.current_user = None
        self.show_auth_screen()

    # -------------------- EFECTO DE FALLO (imagen + sonido) --------------------

    def _init_fail_effects(self):
        self._fail_audios = {}      # nombre de sonido -> control fta.Audio
        self._fail_last_audio = None
        self._fail_played = set()
        self._fail_overlay = None
        self._fail_token = 0
        if fta is None:
            return
        for snd in FAIL_SOUNDS:
            try:
                audio = fta.Audio(src=snd, autoplay=False, volume=1.0)
                try:
                    self.page.services.append(audio)  # Flet 1.x
                except Exception:
                    self.page.overlay.append(audio)  # versiones anteriores
                self._fail_audios[snd] = audio
            except Exception:
                traceback.print_exc()
        try:
            self.page.update()
        except Exception:
            traceback.print_exc()

    def _play_fail_sound(self):
        """Reproduce UN sonido de fallo elegido al azar entre FAIL_SOUNDS."""
        last_snd = getattr(self, "_fail_last_snd", None)
        snd = random.choice([x for x in FAIL_SOUNDS if x != last_snd] or list(FAIL_SOUNDS))
        self._fail_last_snd = snd
        audio = getattr(self, "_fail_audios", {}).get(snd)
        if audio is not None:
            async def _go():
                try:
                    if snd in self._fail_played:
                        try:
                            r = audio.seek(0)
                            if asyncio.iscoroutine(r):
                                await r
                        except Exception:
                            pass
                    self._fail_played.add(snd)
                    r = audio.play()
                    if asyncio.iscoroutine(r):
                        await r
                except Exception:
                    traceback.print_exc()
            try:
                self.page.run_task(_go)
                return
            except Exception:
                pass
        if sys.platform.startswith("win"):
            try:
                import winsound
                winsound.PlaySound(
                    os.path.join(_prepare_assets(), snd),
                    winsound.SND_FILENAME | winsound.SND_ASYNC,
                )
            except Exception:
                pass

    def show_fail_effect(self):
        """Al fallar: sonido de fallo + imagen que aparece unos instantes y se desvanece."""
        try:
            self._play_fail_sound()
            self.page.run_task(self._fail_meme_flash)
        except Exception:
            traceback.print_exc()

    async def _fail_meme_flash(self):
        try:
            await asyncio.sleep(FAIL_IMG_DELAY)
            old = getattr(self, "_fail_overlay", None)
            if old is not None:
                try:
                    self.page.overlay.remove(old)
                except Exception:
                    pass
            self._fail_token += 1
            token = self._fail_token
            last_img = getattr(self, "_fail_last_img", None)
            pool = [im for im in FAIL_IMAGES if im[0] != last_img] or list(FAIL_IMAGES)
            img_name, img_w, img_h = random.choice(pool)
            self._fail_last_img = img_name
            box = ft.Container(
                left=0, top=0, right=0, bottom=0,
                alignment=ft.Alignment(0.0, 0.0),
                bgcolor="#55000000",
                opacity=0.0,
                animate_opacity=220,
                content=ft.Image(src=img_name, width=img_w, height=img_h),
                on_click=lambda e: self.page.run_task(self._hide_fail_meme, token),
            )
            self._fail_overlay = box
            self.page.overlay.append(box)
            self.page.update()
            await asyncio.sleep(0.05)
            box.opacity = 1.0
            self.page.update()
            await asyncio.sleep(1.1)
            await self._hide_fail_meme(token)
        except Exception:
            traceback.print_exc()

    async def _hide_fail_meme(self, token: int):
        box = getattr(self, "_fail_overlay", None)
        if box is None or token != self._fail_token:
            return
        try:
            box.opacity = 0.0
            self.page.update()
            await asyncio.sleep(0.3)
            if self._fail_overlay is box:
                try:
                    self.page.overlay.remove(box)
                except Exception:
                    pass
                self._fail_overlay = None
                self.page.update()
        except Exception:
            traceback.print_exc()

    # -------------------- PROGRESO --------------------

    async def _async_progress_ticker(self):
        while self.is_generating:
            await asyncio.sleep(0.12)
            if self.progress_val < self.progress_target_ceiling:
                diff = self.progress_target_ceiling - self.progress_val
                step = max(0.006, diff * 0.09)
                self.progress_val = min(self.progress_target_ceiling, self.progress_val + step)
            self._sync_live_widgets()
            self.page.update()
        self._sync_live_widgets()
        self.render_center_content()
        self.page.update()

    def _sync_live_widgets(self):
        pct = int(self.progress_val * 100)
        self.progress_container.visible = self.is_generating or self.progress_val > 0
        self.progress_bar_widget.value = self.progress_val
        self.progress_pct_text.value = f"{pct}%"
        self.progress_status_text.value = self.status_message

        self.badge_med_text.value = f"{len(self.exams_data['medium_mcq'])} preguntas"
        self.badge_hard_text.value = f"{len(self.exams_data['hard_mcq'])} preguntas"
        self.badge_short_text.value = f"{len(self.exams_data['short_answers'])} cuestiones"
        self.badge_def_text.value = f"{len(self.exams_data['definitions'])} conceptos"
        self.badge_case_text.value = f"{len(self.exams_data['industrial_cases'])} casos"
        self.unique_topics_text.value = f"Temas únicos: {len(self.global_history)}"
        if self.pdf_paths:
            if len(self.pdf_paths) == 1:
                self.pdf_label_text.value = f"Temario: {os.path.basename(self.pdf_paths[0])}"
            else:
                self.pdf_label_text.value = f"Temario: {len(self.pdf_paths)} PDFs combinados"
            self.pdf_label_text.color = ACCENT_TEAL

