def _prepare_assets() -> str:
    d = os.path.join(tempfile.gettempdir(), "examen_assets")
    os.makedirs(d, exist_ok=True)
    blobs = {FAIL_IMG_NAME: _FAIL_IMG_B64}
    blobs.update(_FAIL_EXTRA_B64)
    for name, b64 in blobs.items():
        try:
            with open(os.path.join(d, name), "wb") as f:
                f.write(base64.b64decode(b64))
        except Exception:
            traceback.print_exc()
    return d


def main(page: ft.Page):
    init_db()
    NexusExamFletApp(page)


if __name__ == "__main__":
    _assets = _prepare_assets()
    # Modo web dinámico: Flet levanta un servidor ASGI
    ft.run(main, assets_dir=_assets, view=ft.AppView.WEB_BROWSER)